def part_with_reltype(self, reltype: str) -> Part:
    """Return |Part| object of part with matching `reltype`.

    Raises |KeyError| if no such relationship exists and |ValueError| if there is more than
    one such relationship.
    """
    rels = self._rels_by_reltype[reltype]
    if not rels:
        raise KeyError("no relationship of type '%s' in collection" % reltype)
    if len(rels) > 1:
        raise ValueError(
            "multiple relationships of type '%s' in collection" % reltype
        )
    return rels[0].target_part

